// --- Manual additions below (not auto-generated) ---

import { ASPECT_COLORS } from "./aspects";

const LEADER_CROP_POSITION: Record<string, string> = {
  "Aurra Sing, Assassin": "60% center",
  "Boba Fett, Any Methods Necessary": "30% center",
  "Boba Fett, Daimyo": "35% center",
  "Chewbacca, Hero of Kessel": "center 0%",
  "Colonel Yularen, This Is Why We Plan": "25% center",
  "Kazuda Xiono, Best Pilot in the Galaxy": "35% center",
  "Poe Dameron, I Can Fly Anything": "35% center",
  "Qui-Gon Jinn, Student of the Living Force": "40% center",
  "Tobias Beckett, People are Predictable": "65% center",
  "Wedge Antilles, Leader of Red Squadron": "35% center",
};

export function getLeaderCropPosition(leaderName: string): string {
  return LEADER_CROP_POSITION[leaderName] ?? "center";
}

export function getBaseAbbrev(baseDisplay: string): string {
  if (baseDisplay.startsWith("Force ")) return "F";
  if (baseDisplay.startsWith("Splash ")) return "S";
  if (/^(Red|Green|Yellow|Blue) \d+HP$/.test(baseDisplay)) return baseDisplay.charAt(0);
  return baseDisplay.split(/\s+/).map((w) => w.charAt(0)).join("").toUpperCase().slice(0, 2);
}

const DISPLAY_COLOR_TO_ASPECT: Record<string, string> = {
  Red: "aggression", Green: "command", Yellow: "cunning", Blue: "vigilance",
};

export function getBaseAspectColor(baseDisplay: string, aspect?: string | null): string | null {
  for (const [name, key] of Object.entries(DISPLAY_COLOR_TO_ASPECT)) {
    if (baseDisplay.includes(name)) return ASPECT_COLORS[key] ?? null;
  }
  if (aspect) return ASPECT_COLORS[aspect.toLowerCase()] ?? null;
  return null;
}

const ASPECT_ICON_MAP: Record<string, string> = {
  aggression: "/images/SWH_Aspects_Aggression.png",
  command: "/images/SWH_Aspects_Command.png",
  cunning: "/images/SWH_Aspects_Cunning.png",
  vigilance: "/images/SWH_Aspects_Vigilance.png",
};

export function getBaseAspectIcon(baseDisplay: string): string | null {
  if (baseDisplay.startsWith("Force ") || baseDisplay.startsWith("Splash ")) return null;
  for (const [name, key] of Object.entries(DISPLAY_COLOR_TO_ASPECT)) {
    if (baseDisplay.includes(name)) return ASPECT_ICON_MAP[key] ?? null;
  }
  return null;
}

export function isForceBase(baseDisplay: string): boolean {
  return baseDisplay.startsWith("Force ");
}

export function isSplashBase(baseDisplay: string): boolean {
  return baseDisplay.startsWith("Splash ");
}

const ALL_COLOR_ASPECTS = ["aggression", "command", "cunning", "vigilance"];

export function getSplashGradient(baseDisplay: string): string {
  const baseAspect = Object.entries(DISPLAY_COLOR_TO_ASPECT)
    .find(([name]) => baseDisplay.includes(name))?.[1];
  const baseHex = baseAspect ? ASPECT_COLORS[baseAspect] : "#666";
  const others = ALL_COLOR_ASPECTS
    .filter((a) => a !== baseAspect)
    .map((a) => ASPECT_COLORS[a]);
  return `conic-gradient(from 180deg, ${baseHex} 0deg, ${baseHex} 180deg, ${others[0]} 180deg, ${others[0]} 240deg, ${others[1]} 240deg, ${others[1]} 300deg, ${others[2]} 300deg, ${others[2]} 360deg)`;
}
